// Minimal structural contract for this unconfigured Worker scaffold.
// Replace/augment it with bindings generated by the selected Cloudflare cf CLI project config.
export interface D1Result<T = unknown> { results?: T[]; success?: boolean; meta?: { changes?: number; last_row_id?: number; duration?: number }; }
export interface D1PreparedStatement {
  bind(...values: unknown[]): D1PreparedStatement;
  first<T = Record<string, unknown>>(columnName?: string): Promise<T | null>;
  all<T = Record<string, unknown>>(): Promise<D1Result<T>>;
  run(): Promise<D1Result>;
}
export interface D1Database {
  prepare(query: string): D1PreparedStatement;
  batch<T extends D1PreparedStatement[]>(statements: T): Promise<D1Result[]>;
}
export interface Env {
  DB?: D1Database;
  TELEGRAM_BOT_TOKEN?: string;
  TELEGRAM_AUTH_MAX_AGE_SECONDS?: string;
  SESSION_TTL_SECONDS?: string;
  APP_ENV?: string;
}
export interface AuthenticatedUser { id: string; telegramUserId: string; displayName: string | null; sessionTokenHash: string; }
export interface AppVariables { requestId: string; user: AuthenticatedUser; }
export type AppBindings = { Bindings: Env; Variables: AppVariables };
